<?php require 'includes/config.php';if(!isLoggedIn()){header('Location:login.php');exit;}$pageTitle='My Account';$st=$pdo->prepare("SELECT * FROM orders WHERE user_id=? ORDER BY id DESC");$st->execute([$_SESSION['user']['id']]);$orders=$st->fetchAll();include 'includes/header.php';?>
